import org.apache.commons.lang3.StringEscapeUtils;

public class Scratch2 {
    public static void main(String[] args) {
        System.out.println("escapeCsv comma: [" + StringEscapeUtils.escapeCsv("a,b") + "]");
        System.out.println("escapeCsv quote: [" + StringEscapeUtils.escapeCsv("a\"b") + "]");
        System.out.println("escapeCsv newline: [" + StringEscapeUtils.escapeCsv("a\nb") + "]");
        System.out.println("escapeCsv plain: [" + StringEscapeUtils.escapeCsv("abc") + "]");
        System.out.println("escapeCsv null: [" + StringEscapeUtils.escapeCsv(null) + "]");
        System.out.println("unescapeCsv quoted comma: [" + StringEscapeUtils.unescapeCsv("\"a,b\"") + "]");
        System.out.println("unescapeCsv quoted doubled quote: [" + StringEscapeUtils.unescapeCsv("\"a\"\"b\"") + "]");
        System.out.println("unescapeCsv null: [" + StringEscapeUtils.unescapeCsv(null) + "]");
        System.out.println("escapeJava tab: [" + StringEscapeUtils.escapeJava("\t") + "]");
        System.out.println("escapeJava unicode above 7f: [" + StringEscapeUtils.escapeJava("é") + "]");
        System.out.println("escapeJava null: [" + StringEscapeUtils.escapeJava(null) + "]");
        System.out.println("escapeHtml3 euro (should be unescaped, not an html3 entity): [" + StringEscapeUtils.escapeHtml3("€") + "]");
        System.out.println("escapeHtml4 euro: [" + StringEscapeUtils.escapeHtml4("€") + "]");
        System.out.println("escapeHtml3 nbsp: [" + StringEscapeUtils.escapeHtml3(" ") + "]");
        System.out.println("unescapeHtml4 unknown entity: [" + StringEscapeUtils.unescapeHtml4("&zzzz;x") + "]");
        System.out.println("escapeXml (deprecated) apos: [" + StringEscapeUtils.escapeXml("'") + "]");
        System.out.println("escapeXml10 apos: [" + StringEscapeUtils.escapeXml10("'") + "]");
        System.out.println("escapeXml11 null byte removed: [" + StringEscapeUtils.escapeXml11("\u0000") + "]");
        System.out.println("escapeXml11 0x0b: [" + StringEscapeUtils.escapeXml11("\u000b") + "]");
        StringEscapeUtils instance = new StringEscapeUtils();
        System.out.println("instance not null: " + (instance != null));
    }
}
EOF
javac -cp target/classes -d _tools/out _tools/out/Scratch2.java && java -cp "_tools/out:target/classes" Scratch2
